package com.huy.enterprise.order; import com.huy.enterprise.common.enums.PurchaseOrderStatus; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; record OrderItemRequest(@NotNull UUID productId,@NotNull @Positive BigDecimal quantity,@NotNull @PositiveOrZero BigDecimal unitPrice){} record OrderRequest(@NotBlank String orderCode,@NotNull UUID supplierId,@NotNull LocalDate orderDate,LocalDate expectedDeliveryDate,String notes,@NotEmpty List<@Valid OrderItemRequest> items){} record OrderStatusRequest(@NotNull PurchaseOrderStatus status){} record OrderItemResponse(UUID productId,String productName,BigDecimal quantity,BigDecimal unitPrice,BigDecimal lineTotal){} record OrderResponse(UUID id,String orderCode,UUID supplierId,String supplierName,LocalDate orderDate,LocalDate expectedDeliveryDate,PurchaseOrderStatus status,BigDecimal totalAmount,String notes,List<OrderItemResponse> items){static OrderResponse from(PurchaseOrder o){return new OrderResponse(o.getId(),o.getOrderCode(),o.getSupplier().getId(),o.getSupplier().getName(),o.getOrderDate(),o.getExpectedDeliveryDate(),o.getStatus(),o.getTotalAmount(),o.getNotes(),o.getItems().stream().map(i->new OrderItemResponse(i.getProduct().getId(),i.getProduct().getName(),i.getQuantity(),i.getUnitPrice(),i.getLineTotal())).toList());}}
